F2 = [['explain pod.spec.containers.imagePullPolicy', 'string + ENUM'], ['explain deployment.spec --recursive', '1276 行字段树'], ['不存在的字段', 'error: field … does not exist'], ['--api-version', '指定 group/version']]
F3 = [['GET /openapi/v3', '51 个路径'], ['/openapi/v3/apis/apps/v1', '702 KiB,166 个 schema'], ['Container.imagePullPolicy', 'enum 与 description'], ['x-kubernetes-group-version-kind', '把 schema 对应到 GVK']]
