steps = [
    step("kubectl api-resources 共 73 种资源,其中命名空间级 35 种、集群级 38 种;kubectl api-versions 有 24 个 group/version。--api-group=apps -o wide 多出 VERBS 和 CATEGORIES 两列(例如 deployments 简称 deploy,verbs 是 create,delete,deletecollection,get,list,patch,update,watch,属于 all 类)。--namespaced=false --verbs=create 只看集群级可创建的 36 种。冷缓存下(--cache-dir 指向新目录)api-resources 只发出 GET /api 和 GET /apis 两个请求——聚合发现一次拿全。", f=fl(F1, cur=[0, 1, 2], done=[3]), t=tl(S(1), mark=lidx(S(1), 'kubectl api-resources:共', '冷缓存'), done=lidx(S(1), 'api-versions', '--api-group=apps')), kv=KV([['发现(discovery)', '/api 和 /apis 返回有哪些 group/version/资源'], ['聚合发现', '一次请求拿全,不用逐个 group 查'], ['VERBS', '告诉你这个资源支持哪些操作']], ['发现'])),
    step("kubectl explain pod.spec.containers.imagePullPolicy 显示 KIND: Pod、VERSION: v1、FIELD: imagePullPolicy <string>、ENUM: Always / IfNotPresent / Never 和描述;explain deployment.spec.strategy.rollingUpdate 先列出 GROUP: apps;explain deployment.spec --recursive 展开 1276 行字段树;不存在的字段 pod.spec.nonexistent 返回 error: field \"nonexistent\" does not exist;--api-version=networking.k8s.io/v1 可以选定组和版本(explain ingress)。", f=fl(F2, cur=[0, 1], mark=[2], done=[3]), t=tl(S(2), mark=lidx(S(2), 'pod.spec.containers.imagePullPolicy', '--recursive'), done=lidx(S(2), 'deployment.spec.strategy', '不存在的字段', '指定 API 版本')), kv=KV([['explain = 读 OpenAPI', '类型、枚举、描述都来自服务端文档'], ['点号路径', 'pod.spec.containers.xxx 逐级往下'], ['--recursive', '一次看完整个字段树']], ['explain'])),
    step("explain 的数据来自 OpenAPI v3 文档:GET /openapi/v3 列出 51 个路径(每个 group/version 一份,如 api/v1、apis);GET /openapi/v3/apis/apps/v1 约 702 KiB,含 166 个 schema,io.k8s.api.apps.v1.Deployment 的字段是 apiVersion、kind、metadata、spec、status;Container.imagePullPolicy 的 schema 里有 type=string、enum=[Always, IfNotPresent, Never] 和 description;Deployment 的 x-kubernetes-group-version-kind=[{group: apps, kind: Deployment, version: v1}] 把 schema 对应到资源。", f=fl(F3, cur=[1, 2], done=[0, 3]), t=tl(S(3), mark=lidx(S(3), 'GET /openapi/v3/apis/apps/v1'), done=lidx(S(3), 'GET /openapi/v3:', 'imagePullPolicy', 'x-kubernetes-group-version-kind')), kv=KV([['OpenAPI v3', '每个 group/version 一份,按需下载'], ['schema', '字段名、类型、枚举、描述都在里面'], ['kubectl 本地缓存', '用 --cache-dir 指定,失效重新下载']], ['OpenAPI v3'])),
    step("创建 CRD gadgets.k100.example.com(简称 gd,spec.size 整数、spec.color 枚举 red / green / blue)后:api-resources 里立刻出现 gadgets,总数 73 → 74;kubectl explain gadget.spec.color 在 1.8 秒后可用,显示 GROUP: k100.example.com、KIND: Gadget、ENUM: red green blue,以及 CRD schema 里写的中文 description。自己的 CRD 写好 schema 和 description,用户就能直接 explain。", f=fl(F4, cur=[2], done=[0, 1, 3]), t=tl(S(4), mark=lidx(S(4), '创建 CRD'), done=lidx(S(4), 'kubectl explain gadget.spec.color', 'kubectl explain gadget.spec 的字段')), kv=KV([['CRD 自动并入', '发现信息和 OpenAPI 同步更新'], ['description 很重要', 'explain 展示的就是你写的描述'], ['几秒的延迟', 'OpenAPI 聚合需要一点时间']], ['CRD 自动并入'])),
]
